long long compute_gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

long long compute_lcm(int a, int b) {
    return (long long)a * b / compute_gcd(a, b);
}

double get_difference(int x1, int y1, int x2, int y2) {
