import java.util.Scanner;

public class Main {
    public static long computeGCD(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    public static long computeLCM(int a, int b) {
        return (long) a * b / computeGCD(a, b);
    }

    public static double getDifference(int x1, int y1, int x2, int y2) {
        long l = computeLCM(y1, y2);
        long diff = Math.abs(l / y1 * x1 - l / y2 * x2);
        return (double) diff / l;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int n = scanner.nextInt();
        double minDifference = 1e15;
        int bestB = 1;
        double targetRatio = (double) x / y;

        for (int i = 1; i <= n; ++i) {
            int left = 1, right = 1000000;
            while (right - left > 1) {
                int mid = (left + right) / 2;
                double ratio = (double) mid / i;
                if (ratio < targetRatio)
                    left = mid;
                else
                    right = mid;
            }
            int candidate = left;
            double diffLeft = getDifference(candidate, i, x, y);
            double diffRight = getDifference(right, i, x, y);
            int chosen = (diffLeft < diffRight) ? candidate : right;
            double currentDiff = getDifference(chosen, i, x, y);
            if (currentDiff < minDifference) {
                minDifference = currentDiff;
                bestB = i;
            }
        }
        System.out.println(bestB + "/" + n);
        scanner.close();
    }
}
